{
  "$schema": "flowstore://spec/variables/v0",
  "variables": {
    "drink_type": {
      "type": "enum",
      "description": "Top-level drink category the patron wants.",
      "values": [
        "coffee",
        "tea"
      ]
    },
    "drink_style": {
      "type": "string",
      "description": "Specific drink within the chosen type (e.g. 'latte', 'americano', 'drip', 'black', 'green', 'herbal')."
    },
    "size": {
      "type": "enum",
      "description": "Cup size.",
      "values": [
        "small",
        "medium",
        "large"
      ]
    },
    "milk": {
      "type": "enum",
      "description": "Milk choice for coffee drinks. 'regular' = whole/2%; 'none' = black coffee.",
      "values": [
        "regular",
        "oat",
        "almond",
        "soy",
        "none"
      ]
    },
    "syrup": {
      "type": "string",
      "description": "Optional flavored syrup (e.g. 'vanilla', 'caramel', 'hazelnut'). 'none' if patron declines."
    },
    "honey": {
      "type": "boolean",
      "description": "Whether the tea should have honey added."
    },
    "order_status": {
      "type": "enum",
      "description": "Final disposition of the order.",
      "values": [
        "confirmed",
        "cancelled"
      ]
    }
  }
}

